/* Minimal runtime for the custom MIPS VM.
   Syscall numbers used by the VM:
     0=read 1=write 2=open 3=close 8=lseek 201=time
   Arguments in $a0-$a2 ($4-$6), return in $v0 ($2).
*/

#define SYS_read   0
#define SYS_write  1
#define SYS_open   2
#define SYS_close  3
#define SYS_lseek  8
#define SYS_time   201

static long mips_syscall3(long num, long a0, long a1, long a2)
{
    register long v0 asm("$2");
    register long _a0 asm("$4") = a0;
    register long _a1 asm("$5") = a1;
    register long _a2 asm("$6") = a2;
    __asm__ volatile (
        "syscall\n\t"
        : "=r"(v0)
        : "r"(_a0), "r"(_a1), "r"(_a2), "r"(num)
        : "$7", "$8", "$9", "$10", "$11", "$12", "$13", "$14", "$15", "$24", "$25", "memory"
    );
    return v0;
}

static long mips_syscall0(long num)
{
    return mips_syscall3(num, 0, 0, 0);
}

static long mips_syscall1(long num, long a0)
{
    return mips_syscall3(num, a0, 0, 0);
}

static long mips_syscall2(long num, long a0, long a1)
{
    return mips_syscall3(num, a0, a1, 0);
}

/* ---- memory ---- */
void *memset(void *dst, int c, size_t n)
{
    unsigned char *d = (unsigned char *)dst;
    while (n--) *d++ = (unsigned char)c;
    return dst;
}

void *memcpy(void *dst, const void *src, size_t n)
{
    unsigned char *d = (unsigned char *)dst;
    const unsigned char *s = (const unsigned char *)src;
    while (n--) *d++ = *s++;
    return dst;
}

void *memmove(void *dst, const void *src, size_t n)
{
    unsigned char *d = (unsigned char *)dst;
    const unsigned char *s = (const unsigned char *)src;
    if (d < s) {
        while (n--) *d++ = *s++;
    } else {
        d += n; s += n;
        while (n--) *--d = *--s;
    }
    return dst;
}

int memcmp(const void *a, const void *b, size_t n)
{
    const unsigned char *p = a, *q = b;
    while (n--) {
        if (*p != *q) return *p - *q;
        p++; q++;
    }
    return 0;
}

/* Simple bump allocator for the freestanding environment */
static unsigned char *heap_ptr = NULL;
static unsigned char *heap_end = NULL;

#define HEAP_SIZE (64 * 1024 * 1024)
static unsigned char heap_area[HEAP_SIZE] __attribute__((aligned(16)));

static void heap_init(void)
{
    if (!heap_ptr) {
        heap_ptr = heap_area;
        heap_end = heap_area + HEAP_SIZE;
    }
}

void *malloc(size_t size)
{
    heap_init();
    size = (size + 15) & ~15UL;
    if (heap_ptr + size > heap_end)
        return NULL;
    void *p = heap_ptr;
    heap_ptr += size;
    return p;
}

void *calloc(size_t nmemb, size_t size)
{
    void *p;
    size_t total = nmemb * size;
    p = malloc(total);
    if (p) memset(p, 0, total);
    return p;
}

void *realloc(void *ptr, size_t size)
{
    void *newp;
    if (!ptr)
        return malloc(size);
    newp = malloc(size);
    if (newp && ptr)
        memcpy(newp, ptr, size); /* over-copies, but safe enough for doom */
    return newp;
}

void free(void *ptr)
{
    (void)ptr;
}

/* ---- strings ---- */
size_t strlen(const char *s)
{
    const char *p = s;
    while (*p) p++;
    return p - s;
}

int strcmp(const char *a, const char *b)
{
    while (*a && *a == *b) { a++; b++; }
    return (unsigned char)*a - (unsigned char)*b;
}

int strncmp(const char *a, const char *b, size_t n)
{
    while (n && *a && *a == *b) { a++; b++; n--; }
    if (!n) return 0;
    return (unsigned char)*a - (unsigned char)*b;
}

char *strcpy(char *dst, const char *src)
{
    char *d = dst;
    while ((*d++ = *src++));
    return dst;
}

char *strncpy(char *dst, const char *src, size_t n)
{
    char *d = dst;
    while (n && (*d++ = *src++)) n--;
    while (n--) *d++ = 0;
    return dst;
}

char *strcat(char *dst, const char *src)
{
    char *d = dst;
    while (*d) d++;
    while ((*d++ = *src++));
    return dst;
}

char *strchr(const char *s, int c)
{
    while (*s) {
        if (*s == (char)c) return (char *)s;
        s++;
    }
    if (c == 0) return (char *)s;
    return NULL;
}

char *strrchr(const char *s, int c)
{
    const char *last = NULL;
    while (*s) {
        if (*s == (char)c) last = s;
        s++;
    }
    if (c == 0) return (char *)s;
    return (char *)last;
}

char *strstr(const char *haystack, const char *needle)
{
    size_t nlen = strlen(needle);
    if (!nlen) return (char *)haystack;
    while (*haystack) {
        if (!strncmp(haystack, needle, nlen))
            return (char *)haystack;
        haystack++;
    }
    return NULL;
}

char *strdup(const char *s)
