int strcasecmp(const char *a, const char *b)
{
    while (*a && *b) {
        int ca = tolower((unsigned char)*a);
        int cb = tolower((unsigned char)*b);
        if (ca != cb) return ca - cb;
        a++; b++;
    }
    return (unsigned char)*a - (unsigned char)*b;
}

int strncasecmp(const char *a, const char *b, size_t n)
{
    while (n && *a && *b) {
        int ca = tolower((unsigned char)*a);
        int cb = tolower((unsigned char)*b);
        if (ca != cb) return ca - cb;
        a++; b++; n--;
    }
    if (!n) return 0;
    return (unsigned char)*a - (unsigned char)*b;
}

double strtod(const char *nptr, char **endptr)
{
    const char *p = nptr;
    double val = 0.0;
    int neg = 0, frac = 0;
    double div = 10.0;
    while (*p == ' ' || *p == '\t') p++;
    if (*p == '-') { neg = 1; p++; }
    else if (*p == '+') p++;
    while (*p >= '0' && *p <= '9') {
        val = val * 10.0 + (*p - '0');
        p++;
    }
    if (*p == '.') {
        p++; frac = 1;
        while (*p >= '0' && *p <= '9') {
            val += (*p - '0') / div;
            div *= 10.0;
            p++;
        }
    }
    (void)frac;
    if (endptr) *endptr = (char *)p;
    return neg ? -val : val;
}

long strtol(const char *nptr, char **endptr, int base)
{
    const char *p = nptr;
    long val = 0;
    int neg = 0;
    while (*p == ' ' || *p == '\t') p++;
    if (*p == '-') { neg = 1; p++; }
    else if (*p == '+') p++;
    if ((base == 0 || base == 16) && p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) {
        p += 2; base = 16;
    } else if (base == 0) {
        if (*p == '0') { base = 8; p++; }
        else base = 10;
    }
    while (*p) {
        int digit;
        if (*p >= '0' && *p <= '9') digit = *p - '0';
        else if (*p >= 'a' && *p <= 'z') digit = *p - 'a' + 10;
        else if (*p >= 'A' && *p <= 'Z') digit = *p - 'A' + 10;
        else break;
        if (digit >= base) break;
        val = val * base + digit;
        p++;
    }
    if (endptr) *endptr = (char *)p;
    return neg ? -val : val;
}

int atoi(const char *s)
{
