/* Minimal FILE struct uses fd in a private field */
struct _FILE_minimal {
    int fd;
    int err;
    int eof;
    int dummy[5];
};

static FILE *make_file(int fd)
{
    FILE *f = malloc(sizeof(FILE));
    if (!f) return NULL;
    memset(f, 0, sizeof(FILE));
    struct _FILE_minimal *m = (struct _FILE_minimal *)f;
    m->fd = fd;
    return f;
}

FILE *fopen(const char *path, const char *mode)
{
    int flags = 0;
    int access = O_RDONLY;
    if (mode[0] == 'r') {
        if (mode[1] == '+') { flags = O_RDWR; access = O_RDWR; }
        else { flags = O_RDONLY; access = O_RDONLY; }
    } else if (mode[0] == 'w') {
        flags = O_WRONLY | O_CREAT | O_TRUNC;
        access = O_WRONLY;
        if (mode[1] == '+') { flags = O_RDWR | O_CREAT | O_TRUNC; access = O_RDWR; }
    } else if (mode[0] == 'a') {
        flags = O_WRONLY | O_CREAT | O_APPEND;
        access = O_WRONLY;
        if (mode[1] == '+') { flags = O_RDWR | O_CREAT | O_APPEND; access = O_RDWR; }
    }
    long fd = mips_syscall2(SYS_open, (long)path, flags);
    if (fd < 0)
        return NULL;
    return make_file((int)fd);
}

int fclose(FILE *f)
{
    if (!f) return 0;
    struct _FILE_minimal *m = (struct _FILE_minimal *)f;
    long ret = mips_syscall1(SYS_close, m->fd);
    free(f);
    return (int)ret;
}

size_t fread(void *ptr, size_t size, size_t nmemb, FILE *f)
{
    struct _FILE_minimal *m = (struct _FILE_minimal *)f;
    size_t total = size * nmemb;
    long n = mips_syscall3(SYS_read, m->fd, (long)ptr, total);
    if (n < 0) return 0;
    return (size_t)n / size;
}

size_t fwrite(const void *ptr, size_t size, size_t nmemb, FILE *f)
{
    struct _FILE_minimal *m = (struct _FILE_minimal *)f;
    size_t total = size * nmemb;
    long n = mips_syscall3(SYS_write, m->fd, (long)ptr, total);
    if (n < 0) return 0;
    return (size_t)n / size;
}

int fseek(FILE *f, long offset, int whence)
{
    struct _FILE_minimal *m = (struct _FILE_minimal *)f;
    long ret = mips_syscall3(SYS_lseek, m->fd, offset, whence);
    return (ret < 0) ? -1 : 0;
}

long ftell(FILE *f)
{
