static void out_char(char **buf, size_t *left, char c)
{
    if (*left > 1) {
        **buf = c;
        (*buf)++;
        (*left)--;
    }
}

static void out_str(char **buf, size_t *left, const char *s)
{
    while (*s) out_char(buf, left, *s++);
}

static void out_num(char **buf, size_t *left, unsigned long val, int base, int upper, int width, char pad)
{
    char tmp[32];
    int i = 0;
    const char *digits = upper ? "0123456789ABCDEF" : "0123456789abcdef";
    if (val == 0) tmp[i++] = '0';
    while (val) { tmp[i++] = digits[val % base]; val /= base; }
    while (i < width) { out_char(buf, left, pad); width--; }
    while (i > 0) out_char(buf, left, tmp[--i]);
}

static int vsnprintf_impl(char *buf, size_t size, const char *fmt, va_list ap)
{
    char *out = buf;
    size_t left = size;
    if (left) left--; /* reserve null */
    while (*fmt) {
        if (*fmt != '%') { out_char(&out, &left, *fmt++); continue; }
        fmt++;
        char pad = ' ';
        int width = 0;
        if (*fmt == '0') { pad = '0'; fmt++; }
        while (*fmt >= '0' && *fmt <= '9') { width = width * 10 + (*fmt - '0'); fmt++; }
        if (*fmt == 'l') fmt++;
        if (*fmt == 'l') fmt++;
        switch (*fmt) {
        case 'd': case 'i': {
            long val = va_arg(ap, long);
            if (val < 0) { out_char(&out, &left, '-'); val = -val; }
            out_num(&out, &left, (unsigned long)val, 10, 0, width, pad);
            break;
        }
        case 'u':
            out_num(&out, &left, va_arg(ap, unsigned long), 10, 0, width, pad);
            break;
        case 'x':
            out_num(&out, &left, va_arg(ap, unsigned long), 16, 0, width, pad);
            break;
        case 'X':
            out_num(&out, &left, va_arg(ap, unsigned long), 16, 1, width, pad);
            break;
        case 'c': {
            char c = (char)va_arg(ap, int);
            out_char(&out, &left, c);
            break;
        }
        case 's': {
            const char *s = va_arg(ap, const char *);
            if (!s) s = "(null)";
            out_str(&out, &left, s);
            break;
        }
        case 'p': {
            unsigned long val = (unsigned long)va_arg(ap, void *);
            out_str(&out, &left, "0x");
            out_num(&out, &left, val, 16, 0, 0, '0');
            break;
        }
        case '%':
            out_char(&out, &left, '%');
            break;
        default:
            out_char(&out, &left, '%');
            out_char(&out, &left, *fmt);
            break;
        }
        if (*fmt) fmt++;
    }
    if (size) *out = 0;
    return (int)(out - buf);
}

int vsnprintf(char *buf, size_t size, const char *fmt, va_list ap)
{
    return vsnprintf_impl(buf, size, fmt, ap);
}

int snprintf(char *buf, size_t size, const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf_impl(buf, size, fmt, ap);
    va_end(ap);
    return n;
}

int sprintf(char *buf, const char *fmt, ...)
{
