int __isoc99_sscanf(const char *s, const char *fmt, ...)
{
    /* Very minimal sscanf: handles %d, %x, %s, %c */
    va_list ap;
    va_start(ap, fmt);
    int count = 0;
    while (*fmt) {
        if (*fmt != '%') { if (*fmt++ != *s++) break; continue; }
        fmt++;
        if (*fmt == 'l') fmt++;
        switch (*fmt) {
        case 'd': {
            int *p = va_arg(ap, int *);
            while (*s == ' ' || *s == '\t') s++;
            int neg = 0;
            if (*s == '-') { neg = 1; s++; }
            else if (*s == '+') s++;
            int val = 0;
            while (*s >= '0' && *s <= '9') { val = val * 10 + (*s - '0'); s++; }
            *p = neg ? -val : val;
            count++;
            break;
        }
        case 'x': {
            unsigned int *p = va_arg(ap, unsigned int *);
            if (s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) s += 2;
            unsigned int val = 0;
            while (1) {
                if (*s >= '0' && *s <= '9') val = val * 16 + (*s - '0');
                else if (*s >= 'a' && *s <= 'f') val = val * 16 + (*s - 'a' + 10);
                else if (*s >= 'A' && *s <= 'F') val = val * 16 + (*s - 'A' + 10);
                else break;
                s++;
            }
            *p = val;
            count++;
            break;
        }
        case 's': {
            char *p = va_arg(ap, char *);
            while (*s == ' ' || *s == '\t') s++;
            while (*s && *s != ' ' && *s != '\t') *p++ = *s++;
            *p = 0;
            count++;
