/* __divdi3 for 64-bit division */
long long __divdi3(long long a, long long b)
{
    int neg = 0;
    unsigned long long ua, ub, q = 0;
    if (a < 0) { neg = !neg; ua = (unsigned long long)(-a); }
    else ua = (unsigned long long)a;
    if (b < 0) { neg = !neg; ub = (unsigned long long)(-b); }
    else ub = (unsigned long long)b;
    if (ub) {
        /* simple shift-subtract */
        unsigned long long bit = 1;
        while (ub < ua && !(ub & (1ULL << 63))) { ub <<= 1; bit <<= 1; }
        while (bit) {
            if (ua >= ub) { ua -= ub; q |= bit; }
            ub >>= 1; bit >>= 1;
        }
    }
    return neg ? -(long long)q : (long long)q;
}

